use std::io::{self, Read};
fn val(s:&str,k:&str)->String{let Some(p)=s.find(k)else{return String::new()};let r=&s[p+k.len()..];let Some(c)=r.find(':')else{return String::new()};let r=r[c+1..].trim_start();if !r.starts_with('"'){return String::new()}let r=&r[1..];r.find('"').map(|e|r[..e].to_string()).unwrap_or_default()}
fn num(s:&str,k:&str)->String{let Some(p)=s.find(k)else{return String::new()};let r=&s[p+k.len()..];let Some(c)=r.find(':')else{return String::new()};r[c+1..].trim_start().split(|x|x==','||x=='}').next().unwrap_or("").trim().to_string()}
fn process(s:&str)->String{let source=val(&s,"\"source_ref\"");let policy=val(&s,"\"version\"");let o=s.split("{\"id\"").nth(1).unwrap_or("");let id=o.split('"').nth(1).unwrap_or("");let f=format!("{{\"{}",o);let label=val(&f,"\"label\"");let model=val(&f,"\"model_ref\"");let score=num(&f,"\"score_millis\"");let start=num(&f,"\"start_ms\"");let end=num(&f,"\"end_ms\"");if source.is_empty()||policy.is_empty()||id.is_empty()||label.is_empty()||model.is_empty()||score.parse::<i32>().ok().map(|v|v>1000).unwrap_or(true){return "{\"result_class\":\"invalid_request\"}".into()}format!("{{\"source_ref\":\"{}\",\"policy_version\":\"{}\",\"evidence\":[{{\"id\":\"evidence:{}\",\"source_ref\":\"{}\",\"detection_id\":\"{}\",\"label\":\"{}\",\"confidence_millis\":{},\"start_ms\":{},\"end_ms\":{},\"model_ref\":\"{}\",\"policy_version\":\"{}\"}}]}}",source,policy,id,source,id,label,score,start,end,model,policy)}
#[cfg(not(test))]
fn main(){let mut s=String::new();io::stdin().read_to_string(&mut s).unwrap();println!("{}",process(&s));}
#[cfg(test)] mod tests { use super::*; #[test] fn helpers_cover_missing_values(){ assert!(val("{}","\"x\"").is_empty()); assert!(num("{}","\"x\"").is_empty()); } #[test] fn valid_is_normalized(){ let o=process(r#"{"source_ref":"a","version":"p","detections":[{"id":"d","label":"x","score_millis":9,"start_ms":0,"end_ms":1,"model_ref":"m"}]}"#); assert!(o.contains("evidence:d")); } #[test] fn invalid_is_rejected(){ assert!(process(r#"{"source_ref":"a","version":"p","detections":[{"id":"d","label":"x","score_millis":1001,"start_ms":0,"end_ms":1,"model_ref":"m"}]}"#).contains("invalid_request")); }}
